using System.Collections.Generic;using Compose.Net;using SharpExtensions;using UnityEngine.UIElements;// ReSharper disable ArrangeNamespaceBodynamespace Compose.Net.Unity.Samples.Behaviors.Content{    internal partial class ButtonSample : ComposeUI    {#pragma warning disable CS0414        [SerializeField] private Texture2D texture = null!;        [SerializeField] private Material material = null!;#pragma warning restore CS0414        [Composable]        protected override void Content()        {            Layout();        }        [Composable]        protected override void Preview()        {            Layout();        }        [Composable]        private void Layout()        {            Column(                verticalArrangement: Arrangement.Center,                horizontalAlignment: Alignment.CenterHorizontally,                modifier: Modifier                    .FillMaxSize(),                content: () =>                {                    Button();                    // Spacer(                    //     Modifier                    //         .Size(300.Dp())                    //         .Float()                    //         .Background(Color.White)                    //         .Custom(                    //             apply: it =>                    //             {                    //                 var element = it.VisualElement();                    //                 var blur = new FilterFunction(FilterFunctionType.Blur);                    //                 blur.AddParameter(new FilterParameter(10.0f)); // радиус в px                    //                             //                 element.style.backdropFilter = new List<FilterFunction> { blur };                    //             },                    //             revert: it => { }                    //         )                    //         .Custom(                    //             apply: it =>                    //             {                    //                 var element = it.VisualElement();                    //                 var shadow = new FilterFunction(FilterFunctionType.DropShadow);                    //                 shadow.AddParameter(new FilterParameter(0f)); // offset-x                    //                 shadow.AddParameter(new FilterParameter(8f)); // offset-y                    //                 shadow.AddParameter(new FilterParameter(20)); // blur radius                    //                 shadow.AddParameter(new FilterParameter(new Color(0f, 0f, 0f, 1f).ToUnityColor())); // color                    //                    //                    //                 element.style.filter = new List<FilterFunction> { shadow, shadow, shadow };                    //             },                    //             revert: it => { }                    //         )                    // );                }            );        }        [Composable]        private static void Button()        {            var interactionSource = Remember(MutableInteractionSource);            var hovered = interactionSource.CollectIsHoveredAsState().Value;            var shadowProgress = AnimateFloatAsState(hovered.ToInt()).Value;            var pressed = interactionSource.CollectIsPressedAsState().Value;            Box(                contentAlignment: Alignment.Center,                modifier: Modifier                    .Height(200.Dp())                    .Width(600.Dp())                    // .Background(                    //     Brush.LinearGradient(                    //         ImmutableStableListOf(                    //             Color.LightGreen,                    //             Color.DodgerBlue                    //         )                    //     ),                    //     RoundedCornerShape(16.Dp())                    // )                    .Background(Color.LightGreen)                    .Padding(16.Dp())                    .Clip(RoundedCornerShape(AnimateFloatAsState(hovered ? 48 : 16).Value.Dp()))                    .BackdropBlur(1.Dp())                    .DropShadow(                        shape: RoundedCornerShape(16.Dp()),                        shadow: Shadow(                            spread: 20.Dp(),                            color: Color.LerpUnclamped(new Color(), Color.Black, shadowProgress)                            ,                            radius: 32.Dp() * shadowProgress                        )                    )                    // .InnerShadow(                    //     shape: RoundedCornerShape(16.Dp()),                    //     shadow: Shadow(                    //         spread: 8.Dp(),                    //         color: Color.LerpUnclamped(new Color(), Color.White with { Alpha = 0.5f }, 1)                    //             ,                    //         radius: 12.Dp()                    //     )                    // )                    .Clickable(                        onClick: () => Debug.Log("Click")                        // interactionSource: null,                        // indication: LocalIndication.Current                    ),                content: () =>                {                    Text(                        text: pressed ? "Clicked" : "Click me",                        color: Color.White,                        fontSize: 80.Sp()                    );                }            );        }    }}